        guarda: H.guarda,
        prossimi: H.prossimi.map(function (x) { return { id: x.id, nome: x.nome }; }),   // (con gli id: chi aspetta sa di essere dentro)
        dopo: H.dopo.map(function (x) { return { id: x.id, nome: x.nome }; }),
